synthesis.recipe_css:
/* ===== GLASS PANE + CARD + CORNER OBJECTS (Chrome, Edge, Safari 15.4+, Firefox 103+) =====
   Numbers come from the sources in the diagnosis list and from renders in headless Chromium 153/156.
   They are a tested starting point. Screenshot at 1920x1080 in Tom's Chrome and tune by eye.

   THE ONE STRUCTURAL RULE: the element that has backdrop-filter is EMPTY (no children) and has no ancestor with
   opacity<1, filter, mask, clip-path, mix-blend-mode or will-change. Cards are SIBLINGS of it, never inside it.

   HTML
   <div class="env"> ...sharp backdrop, shapes and .gobj objects (see 'backdrop') ... </div>
   <div class="stage">
     <div class="pane-glass"></div>    only backdrop-filter element, empty
     <div class="pane-edge"></div>     rim + sheen, pointer-events:none
     <div class="pane-content"> <aside class="rail"/> <main> <section class="card"/> ... </main> </div>
   </div>
*/
:root{
  --inset: 88px;                               /* 1920x1080. Use 72px at 1440x900 and 32px under 1100px wide */
  --pad: 24px;                                 /* pane padding and gap between cards */
  --r-pane: 44px;
  --r-card: calc(var(--r-pane) - var(--pad));  /* concentric = 20px */
  --ink: #0f172a;  --ink-2: #1e293b;
}
@media (max-width:1500px){ :root{ --inset:72px; } }
@media (max-width:1100px){ :root{ --inset:32px; --r-pane:32px; --pad:16px; } }

.env{ position:fixed; inset:0; z-index:0; overflow:hidden; }   /* no filter, no opacity, nothing else */

.stage{
  position:fixed; inset:var(--inset); z-index:1; border-radius:var(--r-pane);
  animation: pane-in .5s cubic-bezier(.2,.7,.2,1) backwards;   /* transform ONLY. No opacity fade on this element or any ancestor */
}
@keyframes pane-in{
  from{ transform: perspective(1600px) rotateX(4deg) translateY(14px) scale(.985); }
  to  { transform: none; }                                     /* end at none; leave no will-change behind */
}

/* PANE: mostly see-through, saturated, lit from the top left */
.pane-glass{
  position:absolute; inset:0; z-index:0; border-radius:inherit;
  background: linear-gradient(135deg, rgba(255,255,255,.34), rgba(255,255,255,.14) 55%, rgba(255,255,255,.26));
  -webkit-backdrop-filter: blur(18px) saturate(1.6) brightness(1.04);   /* literal numbers: no var() inside backdrop-filter (WebKit bug 297620) */
          backdrop-filter: blur(18px) saturate(1.6) brightness(1.04);   /* do NOT put pointer-events:none on this layer: Safari mobile can drop it */
  box-shadow:                                                           /* layered, one light source, tinted to the backdrop hue */
    0 1px 1px   rgba(30,40,110,.06),
    0 4px 4px   rgba(30,40,110,.06),
    0 12px 16px rgba(30,40,110,.08),
    0 28px 48px rgba(30,40,110,.14),
    0 56px 90px rgba(30,40,110,.18);
}

/* EDGE: thin, lit from one side, fading to nothing on the dark side. Replaces the 4px ring, 6px band, 7px line and 40px glow */
.pane-edge{
  position:absolute; inset:0; z-index:1; border-radius:inherit; pointer-events:none;
  border:1px solid rgba(255,255,255,.35);
  box-shadow:
    inset 1.5px 2px 1px -1px rgba(255,255,255,.65),     /* top-left highlight (KeyShot) */
    inset -1px -1px 1px 0   rgba(255,255,255,.35),      /* faint counter-reflection */
    inset 0 -10px 25px      rgba(30,40,110,.10);        /* soft shade along the bottom = thickness */
}
.pane-edge::before{                                      /* directional ring, 1.5px, as in liquid-glass-react */
  content:""; position:absolute; inset:-1px; border-radius:inherit; padding:1.5px;
  background: linear-gradient(135deg,
    rgba(255,255,255,.95) 0%, rgba(255,255,255,.35) 22%, rgba(255,255,255,0) 45%,
    rgba(255,255,255,0) 62%, rgba(255,255,255,.45) 86%, rgba(255,255,255,.85) 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;                            /* Chrome and Safari */
          mask-composite: exclude;                        /* standard */
}

/* CONTENT: flat fills, NO backdrop-filter anywhere in here */
.pane-content{ position:relative; z-index:2; height:100%; display:grid; grid-template-columns:240px 1fr; gap:var(--pad); padding:var(--pad); }
.rail{ background:rgba(255,255,255,.62); border-radius:var(--r-card); }   /* Microsoft: vertical panes get a solid fill */
.card{
  background: rgba(255,255,255,.60);
  border: 1px solid rgba(255,255,255,.85);
  border-radius: var(--r-card);
  box-shadow: 0 1px 1px rgba(30,40,110,.05), 0 8px 24px rgba(30,40,110,.10), inset 0 1.5px 0 rgba(255,255,255,.95);
  color: var(--ink);
}

/* CORNER OBJECTS: live in .env, so the pane blurs the half that is under it */
.gobj{
  position:absolute; width:19vmin; aspect-ratio:1; border-radius:28%;
  background: linear-gradient(145deg, rgba(255,255,255,.30), rgba(255,255,255,.10) 55%, rgba(255,255,255,.22));
  -webkit-backdrop-filter: blur(10px) saturate(1.8);
          backdrop-filter: blur(10px) saturate(1.8);
  border: 1px solid rgba(255,255,255,.45);
  box-shadow: inset 3px 3px 0 rgba(255,255,255,.9), inset -3px -4px 8px rgba(80,100,210,.35), 0 30px 60px rgba(30,40,110,.30);
}
.gobj-a{ top:calc(var(--inset) - 9vmin);    right:calc(var(--inset) - 9vmin); }   /* about 50% over the pane corner */
.gobj-b{ bottom:calc(var(--inset) - 9vmin); right:calc(var(--inset) - 9vmin); }
.gobj-c{ bottom:calc(var(--inset) - 9vmin); left:calc(var(--inset) - 9vmin); }

/* FALLBACKS: no backdrop-filter, or the viewer asked for reduced transparency */
@supports not ((-webkit-backdrop-filter: blur(1px)) or (backdrop-filter: blur(1px))){
  .pane-glass{ background:rgba(244,248,255,.92); }
  .gobj{ background:rgba(244,248,255,.85); }
}
@media (prefers-reduced-transparency: reduce){
  .pane-glass{ -webkit-backdrop-filter:none; backdrop-filter:none; background:rgba(244,248,255,.94); }
  .gobj{ -webkit-backdrop-filter:none; backdrop-filter:none; background:rgba(244,248,255,.90); }
  .card{ background:rgba(255,255,255,.92); }
}
/* prefers-reduced-transparency has limited browser support (MDN), so keep the @supports rule above and offer a settings toggle that adds a class doing the same. */

/* ===== CHROMIUM-ONLY TIER (Chrome, Edge): real edge refraction on the corner objects =====
   Gate with a user-agent check, NOT @supports: Safari parses url() inside backdrop-filter and then draws nothing.
   JS:  const ok = !!navigator.userAgentData?.brands?.some(b => /Chromium/.test(b.brand));
        document.documentElement.classList.toggle('lens-ok', ok);
   CSS: .lens-ok .gobj{ -webkit-backdrop-filter:none; backdrop-filter: url(#lens) blur(1px) saturate(1.6); }
   SVG: <svg width="0" height="0" style="position:absolute"><filter id="lens" x="0" y="0" width="100%" height="100%"
          color-interpolation-filters="sRGB">
          <feImage href="DATA-URL-OF-DISPLACEMENT-MAP" x="0" y="0" width="205" height="205" result="map"/>
          <feDisplacementMap in="SourceGraphic" in2="map" scale="48" xChannelSelector="R" yChannelSelector="G"/>
        </filter></svg>
   The map is a PNG generated by a small script, one per object size (rebuild on resize):
     - size = the object's exact pixel size; 128 = no shift; red = x shift, green = y shift
     - lens band (bezel) at most corner radius minus 1px (56px radius at 205px gives up to 55px)
     - edge profile: convex squircle, height = (1 - (1 - x)^4)^(1/4); bend the ray with Snell's law, refractive index 1.5
     - displacement scale 40-70 (kube.io and liquid-glass-react use 55-70; my untuned test used 46)
     - to fade the lens in or out, animate the feDisplacementMap 'scale' value; no map rebuild needed
   Working examples: github.com/archisvaze/liquid-glass (MIT) and kube.io/blog/liquid-glass-css-svg.

   ===== WHAT IS CSS-ONLY, WHAT NEEDS SVG, WHAT CANNOT BE DONE ON THE WEB TODAY =====
   CSS-only (works everywhere above): see-through tint, blur + saturate + brightness, the directional 1.5px rim,
     inset highlights, layered tinted shadow, thickness strip along an edge (Comeau: 4-6px strip with its own blur(8-12px)
     and brightness), the concentric radii, the opaque fallbacks. Optional small JS: move the rim angle with the pointer.
   SVG-filter-only (Chrome and Edge only; Safari and Firefox ignore it): bending of the backdrop at the edge (lensing),
     colour fringing at the edge (three displacement passes, as liquid-glass-react does), a per-pixel specular rim.
   Cannot be done with a live backdrop in Safari or Firefox today: lensing (WebKit bug 245510 open, PRs unmerged
     2026-11-02). Workarounds exist (WebGL on a page snapshot, e.g. liquidGL; Aave's method of filtering real content;
     or baking the refraction into an image offline), each with costs.
   Impossible on the web at all: Apple's per-frame adaptive shadow and tint, and colour spilling from neighbours.
     Fake the spill with coloured radial glows in the backdrop. Do NOT use -apple-visual-effect: it is a private
     WebKit property that does nothing for web pages. */
